//! Structured operation outcomes returned to every client surface.

use serde::{Deserialize, Serialize};
use std::fmt;

/// Stable identifier for a pending/running operation, so an agent can report
/// blocked work and resume later. Opaque to clients; generated by the broker.
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct OperationId(pub String);

impl OperationId {
    pub fn new(id: impl Into<String>) -> Self {
        OperationId(id.into())
    }
}

impl fmt::Display for OperationId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

/// Structured outcome of an agent-facing operation, per the design doc.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Outcome {
    /// Operation completed (or credential already exists as requested).
    Ready,
    /// Awaiting approval; a stable operation id accompanies this outcome.
    PendingApproval,
    /// Automated issuance unavailable; a human must import the secret.
    NeedsHumanImport,
    /// State conflict (wrong expected version, concurrent lock, etc.).
    Conflict,
    /// Policy or identity denied the operation.
    Denied,
    /// Operation failed; failure details are recorded in the audit trail.
    Failed,
}

impl fmt::Display for Outcome {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            Outcome::Ready => "READY",
            Outcome::PendingApproval => "PENDING_APPROVAL",
            Outcome::NeedsHumanImport => "NEEDS_HUMAN_IMPORT",
            Outcome::Conflict => "CONFLICT",
            Outcome::Denied => "DENIED",
            Outcome::Failed => "FAILED",
        };
        f.write_str(s)
    }
}

/// An operation result: the outcome plus, when relevant, the operation id.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct OperationResult {
    pub outcome: Outcome,
    /// Present for PENDING_APPROVAL and any resumable operation.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub operation: Option<OperationId>,
    /// Human-readable detail; never contains secret material.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub detail: Option<String>,
}

impl OperationResult {
    pub fn ready() -> Self {
        OperationResult {
            outcome: Outcome::Ready,
            operation: None,
            detail: None,
        }
    }

    pub fn pending(op: OperationId) -> Self {
        OperationResult {
            outcome: Outcome::PendingApproval,
            operation: Some(op),
            detail: None,
        }
    }

    pub fn denied(detail: impl Into<String>) -> Self {
        OperationResult {
            outcome: Outcome::Denied,
            operation: None,
            detail: Some(detail.into()),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn outcomes_render_doc_vocabulary() {
        assert_eq!(Outcome::PendingApproval.to_string(), "PENDING_APPROVAL");
        assert_eq!(Outcome::NeedsHumanImport.to_string(), "NEEDS_HUMAN_IMPORT");
        let json = serde_json::to_string(&Outcome::Conflict).unwrap();
        assert_eq!(json, "\"CONFLICT\"");
    }

    #[test]
    fn pending_results_carry_operation_ids() {
        let r = OperationResult::pending(OperationId::new("op-123"));
        assert_eq!(r.outcome, Outcome::PendingApproval);
        let json = serde_json::to_string(&r).unwrap();
        assert!(json.contains("op-123"));
    }

    #[test]
    fn ready_results_omit_optional_fields() {
        let json = serde_json::to_string(&OperationResult::ready()).unwrap();
        assert_eq!(json, "{\"outcome\":\"READY\"}");
    }
}
